func loadGoldenCLI(t *testing.T) *goldenFile {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join("testdata", "goldencli.golden.json"))
	if err != nil {
		t.Fatalf("read golden: %v", err)
	}
	var g goldenFile
	if err := json.Unmarshal(raw, &g); err != nil {
		t.Fatalf("parse golden: %v", err)
	}
	return &g
}

// unfold replaces the golden's folded roots with the real temp roots
// (the generator's fold, reversed).
func unfold(s, appTmp, vaultsTmp string) string {
	s = strings.ReplaceAll(s, "<app>", appTmp)
	s = strings.ReplaceAll(s, "<vaults>", vaultsTmp)
	return s
}

// fold replaces the replay's real temp roots with the golden's folded
// placeholders.
func fold(s, appTmp, vaultsTmp string) string {
	s = strings.ReplaceAll(s, appTmp, "<app>")
	s = strings.ReplaceAll(s, vaultsTmp, "<vaults>")
	return s
}

// decodeConfig turns a raw golden JSON config (with folded paths) into
// an OrderedMap over the real temp roots — through the house decoder
// (integral literals decode as int64, the T-50 law).
func decodeConfig(t *testing.T, raw json.RawMessage, appTmp, vaultsTmp string) *storage.OrderedMap {
	t.Helper()
	fixed := []byte(unfold(string(raw), appTmp, vaultsTmp))
	om, err := storage.DecodeJSON(fixed)
	if err != nil {
		t.Fatalf("decode config: %v", err)
	}
	return om
}

// replayCLI builds the shell bound to a buffer with the frozen clock
// and the golden's seam answers.
func replayCLI(t *testing.T, g *goldenFile, in string) (*CLI, *bytes.Buffer) {
	t.Helper()
	buf := &bytes.Buffer{}
	latency := g.Env.NetStub.LatencyMs
	c := &CLI{
		Out:       buf,
		ErrW:      buf,
		In:        strings.NewReader(in),
		Now:       frozenClock,
		IsATTYIn:  func() bool { return false },
		IsATTYOut: func() bool { return false },
		IsDir: func(p string) bool {
			fi, err := os.Stat(p)
			return err == nil && fi.IsDir()
		},
		ProbeInternet: func(cfg any, timeoutS float64) connectioncheck.ProbeInternetResult {
			return connectioncheck.ProbeInternetResult{
				Online:    g.Env.NetStub.Online,
				Endpoint:  g.Env.NetStub.Endpoint,
				Status:    g.Env.NetStub.Status,
				LatencyMs: latency,
				Detail:    g.Env.NetStub.Detail,
			}
		},
		AIStatus: func(cfg any, timeoutS float64) connectioncheck.AIStatusResult {
			return connectioncheck.AIStatusResult{
				State:  g.Env.AIStub.State,
				Kind:   g.Env.AIStub.Kind,
				Engine: g.Env.AIStub.Engine,
				Detail: g.Env.AIStub.Detail,
				Short:  g.Env.AIStub.Short,
			}
		},
		OllamaModels: func(baseURL string, timeoutS float64) ([]string, error) {
			return g.Env.OllamaModels, nil
		},
	}
	return c, buf
}

// buildEnv rebuilds the crafted environment from the golden's env
// record: the vault dirs, the taxonomy file, config.json +
// bad-config.json, and cache.db with every row the reference's own
// methods produced (the quarantine rows pin the reference's frozen
// stamps — the replay's cache.db is fixture state, inserted directly).
func buildEnv(t *testing.T, g *goldenFile) (appTmp, vaultsTmp string) {
	t.Helper()
	appTmp = t.TempDir()
	vaultsTmp = t.TempDir()
	t.Setenv("GITCURATOR_HOME", appTmp)
	t.Setenv("COLUMNS", "")

	for name, exists := range g.Env.Dirs {
		if exists {
			if err := os.MkdirAll(filepath.Join(vaultsTmp, name), 0o755); err != nil {
				t.Fatalf("mkdir vault dir: %v", err)
			}
		}
	}
	if err := os.MkdirAll(filepath.Join(appTmp, "taxonomy"), 0o755); err != nil {
		t.Fatalf("mkdir taxonomy: %v", err)
	}
	if err := os.WriteFile(filepath.Join(appTmp, "taxonomy", "taxonomy.json"),
		[]byte(`{"categories": []}`+"\n"), 0o644); err != nil {
		t.Fatalf("write taxonomy: %v", err)
	}

	cfg := decodeConfig(t, g.Env.Config, appTmp, vaultsTmp)
	if err := storage.WriteConfigFile(filepath.Join(appTmp, "config.json"), cfg); err != nil {
		t.Fatalf("write config.json: %v", err)
	}
	bad := decodeConfig(t, g.Env.BadConfig, appTmp, vaultsTmp)
	if err := storage.WriteConfigFile(filepath.Join(appTmp, "bad-config.json"), bad); err != nil {
		t.Fatalf("write bad-config.json: %v", err)
	}

	dbPath := filepath.Join(appTmp, "cache.db")
	cache, err := store.NewCacheDB(dbPath)
	if err != nil {
		t.Fatalf("open cache.db: %v", err)
	}
	for _, p := range g.Env.DB.Processed {
		_ = cache.AddProcessed(p.RepoID, p.URL, p.Owner, p.Repo, p.NotePath, p.Category)
	}
	for _, f := range g.Env.DB.Failed {
		cache.AddFailed(f.URL, f.Error)
	}
	// The quarantine rows: the reference drove its own record_404 with
	// the frozen clock (decommissioned_at = 2026-10-17T12:00:00); the
	// store's own stamps ride the live clock, so the replay inserts the
	// pinned rows directly — fixture state for the reader under test.
	for _, q := range g.Env.DB.Quarantine {
		if _, err := cache.SQL().Exec(
			"INSERT OR REPLACE INTO decommissioned_repos"+
				" (url, reason, decommissioned_at, fail_count)"+
				" VALUES (?, ?, ?, ?)",
			q.URL, q.Reason, q.At, q.Count); err != nil {
			t.Fatalf("insert quarantine row: %v", err)
		}
	}
	cache.Close()

	ns, err := notestate.New(dbPath)
	if err != nil {
		t.Fatalf("open note state: %v", err)
	}
	for _, u := range g.Env.DB.NoteState.Upserts {
		cat := u[4]
		if err := ns.Upsert(u[0], u[1], u[2], u[3], &cat, nil, false); err != nil {
			t.Fatalf("note upsert: %v", err)
		}
	}
	for _, cr := range g.Env.DB.NoteState.Corrections {
		fromCat, toCat := cr[2], cr[3]
		if err := ns.LogCorrection(cr[0], cr[1], &fromCat, &toCat, cr[4], cr[5], cr[6]); err != nil {
			t.Fatalf("log correction: %v", err)
		}
	}
	for _, d := range g.Env.DB.NoteState.Dismissed {
		if err := ns.Dismiss(d[0], d[1], ""); err != nil {
			t.Fatalf("note dismiss: %v", err)
		}
	}
	ns.Close()

	ws, err := websitepipeline.NewWebsiteStateDB(dbPath)
	if err != nil {
		t.Fatalf("open website state: %v", err)
	}
	for _, p := range g.Env.DB.Websites.Processed {
		if err := ws.MarkProcessed(p[0], p[1], p[2], p[3], p[4]); err != nil {
			t.Fatalf("website mark_processed: %v", err)
		}
	}
	for _, r := range g.Env.DB.Websites.Retries {
		url, _ := r[0].(string)
		errMsg, _ := r[1].(string)
		count, _ := r[2].(float64)
		for i := 0; i < int(count); i++ {
			if err := ws.EnqueueRetry(url, errMsg); err != nil {
				t.Fatalf("website enqueue_retry: %v", err)
			}
		}
	}
	for _, d := range g.Env.DB.Websites.Dismissed {
		reason := "note deleted by owner"
		if len(d) > 1 && d[1] != "" {
			reason = d[1]
		}
		if err := ws.Dismiss(d[0], reason); err != nil {
			t.Fatalf("website dismiss: %v", err)
		}
	}
	ws.Close()
	return appTmp, vaultsTmp
}

// assertBytesEq fails with a display-safe diff: the raw strings are
// dumped with Go %q quoting (every control byte — including the ANSI
// escapes — becomes a visible escape, immune to display mangling).
func assertBytesEq(t *testing.T, name, got, want string) {
	t.Helper()
	if got == want {
		return
	}
	t.Fatalf("%s mismatch\n--- got ---\n%q\n--- want ---\n%q", name, got, want)
}

// TestGoldenCLI replays every ported section of the golden.
func TestGoldenCLI(t *testing.T) {
	g := loadGoldenCLI(t)
	appTmp, vaultsTmp := buildEnv(t, g)

	t.Run("Banner", func(t *testing.T) {
		c, buf := replayCLI(t, g, "")
		c.Banner()
		assertBytesEq(t, "banner", buf.String(), g.Banner)
	})

	t.Run("PaintShapes", func(t *testing.T) {
		// colors FORCED on for the codes matrix (the reference's own
		// force flag), then back off — sequential, never parallel.
		EnableColors(true)
		on := map[string]string{
			"plain":       Paint("x"),
			"bold":        Paint("x", cBold),
			"cyan_bold":   Paint("x", cCyan, cBold),
			"dim":         Paint("x", cDim),
			"red":         Paint("x", cRed),
			"green":       Paint("x", cGreen),
			"yellow":      Paint("x", cYellow),
			"magenta":     Paint("x", cMagenta),
			"empty_codes": Paint("x", ""),
		}
		for k, want := range g.PaintShapes.CodesOn {
			if got := on[k]; got != want {
				t.Errorf("codes_on[%q] = %q, want %q", k, got, want)
			}
		}
		DisableColors()
		off := map[string]string{
			"plain":     Paint("x"),
			"bold":      Paint("x", ""),
			"cyan_bold": Paint("x", "", ""),
		}
		for k, want := range g.PaintShapes.CodesOff {
			if got := off[k]; got != want {
				t.Errorf("codes_off[%q] = %q, want %q", k, got, want)
			}
		}
	})

	t.Run("MaskAndFriends", func(t *testing.T) {
		gotMask := []string{
			Mask("", 4),
			Mask("abc", 4),
			Mask("abcd", 4),
			Mask("abcdefgh", 4),
			Mask("abcdefghijklmnop", 4),
			Mask("abcdefghijklmnopqrstuvwxyz0123456789", 4),
		}
		for i, want := range g.PaintShapes.Mask {
			if gotMask[i] != want {
				t.Errorf("mask[%d] = %q, want %q", i, gotMask[i], want)
			}
		}
		gotTok := []string{
			MaskToken("", 4, 4),
			MaskToken("abc", 4, 4),
			MaskToken("abcdefghijk", 4, 4),
			MaskToken("fake-github-token-0123456789", 4, 4),
		}
		for i, want := range g.PaintShapes.MaskToken {
			if gotTok[i] != want {
				t.Errorf("mask_token[%d] = %q, want %q", i, gotTok[i], want)
			}
		}
		if got := Rule(); got != g.PaintShapes.Rule {
			t.Errorf("rule = %q, want %q", got, g.PaintShapes.Rule)
		}
		gotBars := []string{
			RenderBar(0, 0, 20),
			RenderBar(0, 40, 20),
			RenderBar(1, 40, 20),
			RenderBar(12, 40, 20),
			RenderBar(30, 40, 20),
			RenderBar(40, 40, 20),
			RenderBar(40, 40, 20),
			RenderBar(50, 40, 20),
			RenderBar(12, 40, 7),
		}
		for i, want := range g.PaintShapes.RenderBar {
			if gotBars[i] != want {
				t.Errorf("render_bar[%d] = %q, want %q", i, gotBars[i], want)
			}
		}
		gotStrip := []string{
			StripANSI("plain"),
			StripANSI("\x1b[1mbold\x1b[0m plain"),
			StripANSI("\x1b[31;1mred bold\x1b[0m"),
		}
		for i, want := range g.PaintShapes.StripANSI {
			if gotStrip[i] != want {
				t.Errorf("strip_ansi[%d] = %q, want %q", i, gotStrip[i], want)
			}
		}
		wantStyles := map[string][2]string{}
		for lvl, pair := range g.PaintShapes.LevelStyles {
			if len(pair) == 2 {
				wantStyles[lvl] = [2]string{pair[0], pair[1]}
			}
		}
		for _, lvl := range []string{"info", "success", "warning", "error", "dim", "unknown"} {
			want := wantStyles[lvl]
			color, icon := levelStyle(lvl)
			if color != want[0] || icon != want[1] {
				t.Errorf("level_style[%q] = (%q,%q), want (%q,%q)", lvl, color, icon, want[0], want[1])
			}
		}
		if SpinFrames != g.PaintShapes.SpinFrames {
			t.Errorf("spin frames = %q, want %q", SpinFrames, g.PaintShapes.SpinFrames)
		}
	})

	t.Run("CliPrint", func(t *testing.T) {
		cases := [][2]string{
			{"hello", "info"}, {"it worked", "success"},
			{"be careful", "warning"}, {"it broke", "error"},
			{"quiet note", "dim"}, {"", "info"},
		}
		for i, c2 := range cases {
			c, buf := replayCLI(t, g, "")
			c.CliPrint(c2[0], c2[1])
			assertBytesEq(t, "cli_print", buf.String(), g.CliprintLines[i])
		}
	})

	t.Run("SyncEssentials", func(t *testing.T) {
		for i, tc := range g.SyncEssentials {
			cfg := decodeConfig(t, tc.Config, appTmp, vaultsTmp)
			got := SyncMissingEssentials(cfg, func(string) bool { return tc.Isdir })
			if len(got) != len(tc.Problems) {
				t.Errorf("case %d: %d problems, want %d: %v", i, len(got), len(tc.Problems), got)
				continue
			}
			for j, want := range tc.Problems {
				if got[j] != want {
					t.Errorf("case %d problem %d = %q, want %q", i, j, got[j], want)
				}
			}
		}
	})

	t.Run("SyncButton", func(t *testing.T) {
		for i, tc := range g.SyncButton {
			// The scripted stdin: one line per beat (the fake _input
			// answered without EOF unless the beat says eof).
			in := tc.Answer + "\n"
			if tc.Eof {
				in = ""
			}
			c, buf := replayCLI(t, g, in)
			got := c.SyncConfirmPrompt(tc.AssumeYes, tc.Tty)
			if got != tc.Sync {
				t.Errorf("beat %d: verdict %v, want %v", i, got, tc.Sync)
			}
			wantPrompt := strings.Join(tc.Prompts, "")
			assertBytesEq(t, "beat prompt", buf.String(), wantPrompt)
		}
	})

	t.Run("SyncFailureCard", func(t *testing.T) {
		c, buf := replayCLI(t, g, "")
		c.SyncFailureCard([]string{
			"the vault path is empty",
			"the Ollama model is not configured",
		}, "")
		assertBytesEq(t, "failure card", buf.String(), g.SyncFailureCard)
	})

	t.Run("StatusCard", func(t *testing.T) {
		c, buf := replayCLI(t, g, "")
		rc := c.Run([]string{"--status", "--config", filepath.Join(appTmp, "config.json")})
		if rc != g.StatusCard.RC {
			t.Fatalf("rc = %d, want %d", rc, g.StatusCard.RC)
		}
		assertBytesEq(t, "status card", fold(buf.String(), appTmp, vaultsTmp), g.StatusCard.Output)
	})

	t.Run("StatusNoConfig", func(t *testing.T) {
		c, buf := replayCLI(t, g, "")
		rc := c.Run([]string{"--status", "--config", filepath.Join(appTmp, "missing-config.json")})
		if rc != g.StatusNoConfig.RC {
			t.Fatalf("rc = %d, want %d", rc, g.StatusNoConfig.RC)
		}
		assertBytesEq(t, "status no-config", fold(buf.String(), appTmp, vaultsTmp), g.StatusNoConfig.Output)
	})

	t.Run("SyncNoConfig", func(t *testing.T) {
		c, buf := replayCLI(t, g, "")
		rc := c.Run([]string{"--sync", "--config", filepath.Join(appTmp, "missing-config.json")})
		if rc != g.SyncNoConfig.RC {
			t.Fatalf("rc = %d, want %d", rc, g.SyncNoConfig.RC)
		}
		assertBytesEq(t, "sync no-config", fold(buf.String(), appTmp, vaultsTmp), g.SyncNoConfig.Output)
	})

	t.Run("SyncBadConfig", func(t *testing.T) {
		c, buf := replayCLI(t, g, "")
		rc := c.Run([]string{"--sync", "--config", filepath.Join(appTmp, "bad-config.json")})
		if rc != g.SyncBadConfig.RC {
			t.Fatalf("rc = %d, want %d", rc, g.SyncBadConfig.RC)
		}
		assertBytesEq(t, "sync bad-config", fold(buf.String(), appTmp, vaultsTmp), g.SyncBadConfig.Output)
	})

	t.Run("ListDead", func(t *testing.T) {
		c, buf := replayCLI(t, g, "")
		rc := c.Run([]string{"--list-dead", "--config", filepath.Join(appTmp, "config.json")})
		if rc != g.ListDead.RC {
			t.Fatalf("rc = %d, want %d", rc, g.ListDead.RC)
		}
		assertBytesEq(t, "list-dead", fold(buf.String(), appTmp, vaultsTmp), g.ListDead.Output)
	})

	t.Run("ResetDead", func(t *testing.T) {
		// LAST — it mutates the quarantine (the golden drove it last
		// for the same reason).
		c, buf := replayCLI(t, g, "")
		rc := c.Run([]string{"--reset-dead"})
		if rc != g.ResetDead.RC {
			t.Fatalf("rc = %d, want %d", rc, g.ResetDead.RC)
		}
		assertBytesEq(t, "reset-dead", fold(buf.String(), appTmp, vaultsTmp), g.ResetDead.Output)
	})

	t.Run("HelpCardReference", func(t *testing.T) {
		// The reference's no-flag card is the RECORD of the pre-Option-B
		// surface — intentionally NOT byte-compared (the Go port's
		// honest card drops the Telethon-only lines; see cli_test.go's
		// snapshot). The assertion proves the record is present and
		// carries the lines the Go surface refuses — the documented
		// divergence.
		out := g.HelpCardReference.Output
		for _, line := range []string{
			"--mark-read", "--from-id A --to-id B",
			"--offset-start A --count N", "--single-id N", "--login",
		} {
			if !strings.Contains(out, line) {
				t.Errorf("the reference record lost the Telethon line %q", line)
			}
		}
		if g.HelpCardReference.RC != 0 {
			t.Errorf("reference help rc = %d, want 0", g.HelpCardReference.RC)
		}
	})
}

// TestGoldenCLIMutation proves the differential has teeth: one byte
// changed in the golden's status card section must fail the replay's
// comparison.
func TestGoldenCLIMutation(t *testing.T) {
	g := loadGoldenCLI(t)
	appTmp, vaultsTmp := buildEnv(t, g)
	mutated := strings.Replace(g.StatusCard.Output,
		"Processed repos        2", "Processed repos        3", 1)
	if mutated == g.StatusCard.Output {
		t.Fatalf("mutation did not bite (pattern missing)")
	}
	c, buf := replayCLI(t, g, "")
	rc := c.Run([]string{"--status", "--config", filepath.Join(appTmp, "config.json")})
	if rc != g.StatusCard.RC {
		t.Fatalf("rc = %d, want %d", rc, g.StatusCard.RC)
	}
	got := fold(buf.String(), appTmp, vaultsTmp)
	if got == mutated {
		t.Fatalf("the mutated golden passed — the differential has no teeth")
	}
	if got != g.StatusCard.Output {
		t.Fatalf("the real replay diverged from the unmutated golden")
	}
}
